"""Deterministic synthetic clinic-trial fixture; not an agent or visual proof."""
import json
import sys
from pathlib import Path


def generate(brief):
    title = str(brief.get("clinic_hypothesis", "A synthetic clinic follow-up workflow"))
    sample = brief.get("sample_data", "SYNTHETIC SAMPLE: no real clinic or patient data")
    Path("artifacts").mkdir(exist_ok=True)
    Path("artifacts/clinic-hypothesis.md").write_text(
        "# 合成诊所假设 / Synthetic clinic hypothesis\n\n" + title +
        "\n\n**合成演示 / Synthetic demo only.** Not generated by a real agent.\n",
        encoding="utf-8")
    Path("artifacts/buyer-ledger.md").write_text(
        "# 买家问题与样例台账 / Buyer questions and sample ledger\n\n" +
        "## 合成数据 / Synthetic sample data\n\n" + str(sample) +
        "\n\n## 买家问题 / Buyer questions\n\n- Who owns follow-up?\n- What evidence would justify a pilot?\n",
        encoding="utf-8")
    print(json.dumps({"artifacts": ["artifacts/clinic-hypothesis.md", "artifacts/buyer-ledger.md"]}))


def validate(generated):
    ok = bool(generated.get("artifacts"))
    for path in generated.get("artifacts", []):
        file = Path(path)
        ok = ok and file.is_file() and file.suffix == ".md" and "Synthetic" in file.read_text(encoding="utf-8")
    print(json.dumps({"passed": bool(ok)}))
    return 0 if ok else 1


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else "generate"
    payload = json.load(sys.stdin)
    raise SystemExit(validate(payload) if mode == "validate" else (generate(payload) or 0))
